using System.Linq;
using UnityEngine;
namespace QuietDread {
public partial class Game {
 bool IsBattleHudPoint(){float s=Mathf.Min(Screen.width/1600f,Screen.height/900f);float x=(Input.mousePosition.x-(Screen.width-1600*s)/2)/s,y=(Screen.height-Input.mousePosition.y-(Screen.height-900*s)/2)/s;return !battle.deployment&&y>=739&&y<=775||y>=103&&y<=138&&x>=490&&x<=1110;}
 void RelayReadouts(){int i=0;foreach(var relay in battle.Objectives){int own=battle.Control(0,relay),foe=battle.Control(1,relay);float x=490+i*205;Frame(x,104,195,30,own==foe?new Color(.13f,.16f,.17f):own>foe?new Color(.08f,.24f,.23f):new Color(.29f,.1f,.09f));Text("RELAY "+(i+1)+"  "+own+" : "+foe+(own==foe?"  TIED":own>foe?"  YOURS":"  ENEMY"),x+8,109,180,22,new GUIStyle(small){fontSize=12});i++;}}
 string actionHint;
 bool BattleActionButton(Soldier u,string label,string key,float x,float y){string reason=battle.ActionUnavailable(u,key);bool result=Btn(label,x,y,112,35,action==key,reason==null&&battle.turn==0);if(new Rect(x,y,112,35).Contains(Event.current.mousePosition))actionHint=reason??ActionInstructions(key);return result;}
 string ActionInstructions(string key){switch(key){case "move":return "MOVE · 1 AP. Click a highlighted empty cell. Difficult terrain consumes extra movement.";case "fire":return "FIRE / MELEE · 1 AP and this turn's attack. Point at an enemy for odds; click to attack.";case "rally":return "RALLY · 1 AP. Remove up to 2 suppression and 1 Pressure; lost AP is not restored.";case "charge":return "CHARGE · 2 AP and the attack. Click an enemy reachable by a legal charge path.";case "orders":return "ORDERS · 1 AP. Click an unordered ally within 4: +15 accuracy and +1 control.";case "brace":return "BRACE · 1 AP. Prepare artillery to fire. Moving removes bracing.";case "heal":return "HEAL · 1 AP, the attack and 3 Aether. Click an injured ally within 6; restore 8 HP.";case "ward":return "WARD · 1 AP and the attack. Click an ally within 6; grant 6 ward HP.";case "repair":return "REPAIR · 1 AP. Click an injured vehicle or titan within 3.";case "signature":return "TITAN SIGNATURE · Usually 2 AP and the attack. Targeted powers require a battlefield target.";case "tunnel":return "TUNNEL · Click empty legal ground beside a relay. Deepdelve costs 1 AP; otherwise 2.";default:return key.ToUpperInvariant()+" · Choose an appropriate target within the ability's range.";}}
 void CycleReadyUnit(){var candidates=battle.Living(0).Where(u=>battle.deployment||u.ap>0).ToList();if(candidates.Count==0){battle.Note("No friendly formations have AP remaining.");return;}int index=candidates.FindIndex(u=>u.id==selected);Select(candidates[(index+1)%candidates.Count]);}
}
}
